return [
  {
    json: {
      title: "NASA James Webb Uncovers Mystery in Deep Space",
      link: "https://www.nasa.gov/news/webb-deep-space-mystery",
      guid: "https://www.nasa.gov/news/webb-deep-space-mystery",
      description: "Astronomers find unprecedented cosmic black hole structure that rewrites history.",
      pubDate: new Date().toISOString(),
      _meta_source: "NASA",
      _meta_category: "SPACE"
    }
  },
  {
    json: {
      title: "Ancient Tomb Secret Discovered in Egypt",
      link: "https://www.smithsonianmag.com/history/ancient-tomb-secret",
      guid: "https://www.smithsonianmag.com/history/ancient-tomb-secret",
      description: "Archaeologists unearth lost civilization ruins and forbidden tomb mystery.",
      pubDate: new Date().toISOString(),
      _meta_source: "Smithsonian History",
      _meta_category: "HISTORY"
    }
  },
  {
    json: {
      title: "Quantum Paradox Reveals Alien Particle Anomaly",
      link: "https://www.sciencedaily.com/releases/quantum-paradox-anomaly",
      guid: "https://www.sciencedaily.com/releases/quantum-paradox-anomaly",
      description: "Scientists detect bizarre signal in deep sea laboratory.",
      pubDate: new Date().toISOString(),
      _meta_source: "ScienceDaily Space",
      _meta_category: "SCIENCE"
    }
  },
  {
    json: {
      title: "Quarterly Administrative Committee Meeting Briefing",
      link: "https://www.nasa.gov/news/quarterly-meeting-schedule",
      guid: "https://www.nasa.gov/news/quarterly-meeting-schedule",
      description: "Advisory board holds annual conference to review schedule update and contract awarded.",
      pubDate: new Date().toISOString(),
      _meta_source: "NASA",
      _meta_category: "SPACE"
    }
  }
];

// Clean HTML entities and markup
function cleanText(text) {
  if (!text) return "";
  return String(text)
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, "\"")
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

// Access persistent static data across scheduled executions
const staticData = $getWorkflowStaticData('global');
staticData.seenUrls = staticData.seenUrls || {};
const now = Date.now();
const THIRTY_DAYS_MS = 30 * 24 * 60 * 60 * 1000;

// Prune expired URLs to prevent unbounded memory growth
for (const [url, timestamp] of Object.entries(staticData.seenUrls)) {
  if (now - timestamp > THIRTY_DAYS_MS) {
    delete staticData.seenUrls[url];
  }
}

const seenInBatch = new Set();
const normalizedItems = [];

for (const item of $input.all()) {
  try {
    const data = item.json || {};
    const rawTitle = data.title || data["title:"] || "";
    const title = cleanText(rawTitle);
    const rawUrl = data.link || data.guid || data.origlink || "";
    const sourceUrl = (typeof rawUrl === "string") ? rawUrl.trim() : (data.guid?.["#text"] || "");

    if (!title || !sourceUrl) continue;

    const normalizedTitle = title.toLowerCase().replace(/[^a-z0-9]/g, "");

    // Check both in-batch duplicates and persistent history from previous runs
    if (seenInBatch.has(sourceUrl) || seenInBatch.has(normalizedTitle) || staticData.seenUrls[sourceUrl]) {
      continue;
    }

    seenInBatch.add(sourceUrl);
    seenInBatch.add(normalizedTitle);
    staticData.seenUrls[sourceUrl] = now;

    const rawDesc = data.contentSnippet || data.description || data.summary || data.content || "";
    const description = cleanText(rawDesc);

    let pubDateIso = new Date().toISOString();
    const rawDate = data.pubDate || data.isoDate || data.date;
    if (rawDate) {
      try {
        const parsed = new Date(rawDate);
        if (!isNaN(parsed.getTime())) {
          pubDateIso = parsed.toISOString();
        }
      } catch (e) {}
    }

    const sourceName = data._meta_source || "RSS Source";
    let category = data._meta_category || "SCIENCE";

    const fullText = (title + " " + description).toLowerCase();
    if (fullText.includes("mystery") || fullText.includes("unexplained") || fullText.includes("bizarre") || fullText.includes("enigma") || fullText.includes("anomal")) {
      category = "MYSTERIES";
    } else if (fullText.includes("ancient") || fullText.includes("archaeolog") || fullText.includes("century") || fullText.includes("civilization") || fullText.includes("histor")) {
      category = "HISTORY";
    } else if (fullText.includes("space") || fullText.includes("nasa") || fullText.includes("galaxy") || fullText.includes("planet") || fullText.includes("asteroid") || fullText.includes("telescope") || fullText.includes("cosm")) {
      category = "SPACE";
    }

    normalizedItems.push({
      json: {
        title,
        source: sourceName,
        source_url: sourceUrl,
        original_article_url: sourceUrl,
        publication_date: pubDateIso,
        description,
        category,
        discovery_timestamp: new Date().toISOString()
      }
    });
  } catch (err) {
    continue;
  }
}

return normalizedItems;

const items = $input.all();
const scoredItems = [];

const HIGH_IMPACT_HOOKS = [
  "mystery", "unexplained", "secret", "ancient", "origin", "discovery",
  "bizarre", "first time", "unprecedented", "hidden", "black hole",
  "deep space", "alien", "extinction", "cataclysm", "lost civilization",
  "forbidden", "shocking", "quantum", "rewrites history", "paradox",
  "dark matter", "voyager", "james webb", "exoplanet", "tomb", "ruins"
];

const MODERATE_ENGAGEMENT_HOOKS = [
  "reveals", "breakthrough", "new evidence", "astronomers", "scientists find",
  "anomaly", "signal", "danger", "collision", "investigation", "uncovered",
  "rare", "unknown", "deep sea", "fossil", "prehistoric", "expedition"
];

const LOW_VALUE_ADMIN_TERMS = [
  "quarterly report", "budget", "meeting", "conference", "appointment",
  "administrator", "statement on", "press release", "contract awarded",
  "briefing", "schedule update", "symposium", "advisory", "grant"
];

for (const item of items) {
  try {
    const d = item.json || {};
    const title = d.title || "";
    const description = d.description || "";
    const combinedText = (title + " " + description).toLowerCase();

    let score = 50;
    const scoreBreakdown = ["Base neutral score: +50"];

    let highImpactHits = 0;
    for (const kw of HIGH_IMPACT_HOOKS) {
      if (combinedText.includes(kw)) highImpactHits++;
    }
    if (highImpactHits > 0) {
      const boost = Math.min(25, highImpactHits * 8);
      score += boost;
      scoreBreakdown.push(`High curiosity hook keywords (${highImpactHits} match): +${boost}`);
    }

    let modImpactHits = 0;
    for (const kw of MODERATE_ENGAGEMENT_HOOKS) {
      if (combinedText.includes(kw)) modImpactHits++;
    }
    if (modImpactHits > 0) {
      const boost = Math.min(15, modImpactHits * 5);
      score += boost;
      scoreBreakdown.push(`Scientific discovery terms (${modImpactHits} match): +${boost}`);
    }

    let adminHits = 0;
    for (const term of LOW_VALUE_ADMIN_TERMS) {
      if (combinedText.includes(term)) adminHits++;
    }
    if (adminHits > 0) {
      const penalty = adminHits * 20;
      score -= penalty;
      scoreBreakdown.push(`Administrative/routine notice terms (${adminHits} match): -${penalty}`);
    }

    if (description.length >= 200) {
      score += 10;
      scoreBreakdown.push("Rich editorial summary (>=200 chars): +10");
    } else if (description.length < 50) {
      score -= 10;
      scoreBreakdown.push("Very brief summary (<50 chars): -10");
    }

    if (d.publication_date) {
      try {
        const pubTime = new Date(d.publication_date).getTime();
        if (!isNaN(pubTime)) {
          const hoursOld = (Date.now() - pubTime) / (1000 * 60 * 60);
          if (hoursOld <= 24 && hoursOld >= 0) {
            score += 10;
            scoreBreakdown.push("Recent publication (<24h): +10");
          } else if (hoursOld <= 72 && hoursOld >= 0) {
            score += 5;
            scoreBreakdown.push("Recent publication (<72h): +5");
          }
        }
      } catch (e) {}
    }

    const finalScore = Math.max(0, Math.min(100, Math.round(score)));
    const isLongCandidate = finalScore >= 65 && description.length >= 100;
    const isShortsCandidate = finalScore >= 50 && (highImpactHits >= 1 || modImpactHits >= 1);
    const status = finalScore >= 70 ? "candidate_for_research" : "discovered";

    scoredItems.push({
      json: {
        ...d,
        editorial_priority_score: finalScore,
        score_type: "heuristic_editorial_score",
        score_notes: "Heuristic documentary potential score based on narrative tension and discovery keywords; does not reflect actual YouTube audience analytics.",
        score_breakdown: scoreBreakdown,
        is_long_documentary_candidate: isLongCandidate,
        is_shorts_candidate: isShortsCandidate,
        recommended_format: isLongCandidate ? "8-12 min Long Documentary" : (isShortsCandidate ? "60s Vertical Short" : "Background Archive"),
        status: status
      }
    });
  } catch (err) {
    continue;
  }
}

scoredItems.sort((a, b) => b.json.editorial_priority_score - a.json.editorial_priority_score);
return scoredItems;

// Limit to top 5 candidates per run to protect API quotas
const candidates = $input.all();
return candidates.slice(0, 5);

const items = $input.all();

return items.map(entry => {
  const item = entry.json || {};
  const promptText = `You are the Executive Senior Science & Documentary Editor for VOIDORA, a prestigious English documentary channel covering Space, Science, History, and Mysteries.

Analyze this candidate research topic and produce a structured pre-production editorial brief:

Topic Title: ${item.title || "Untitled"}
Source: ${item.source || "Unknown"}
Category: ${item.category || "SCIENCE"}
Canonical URL: ${item.original_article_url || item.source_url || ""}
Summary: ${item.description || "No summary provided"}

REQUIREMENTS:
1. Provide an insightful topic_analysis explaining why this topic captures human curiosity.
2. Formulate a unique documentary_angle (e.g. historical mystery, cosmic paradigm shift, existential inquiry).
3. Create a compelling suggested_title for YouTube (dignified, intriguing, non-clickbait).
4. Provide exactly 3 captivating storytelling_hooks for the video cold open.
5. List specific facts_requiring_verification (empirical or historical claims that must be confirmed).
6. Suggest real primary_research_sources (academic journals, NASA data archives, peer-reviewed institutions).
7. Rate long_video_potential (HIGH/MEDIUM/LOW with brief justification).
8. Rate shorts_potential (HIGH/MEDIUM/LOW with brief justification).

Return STRICTLY a JSON object matching the requested schema.`;

  return {
    json: {
      ...item,
      gemini_request_payload: {
        contents: [
          {
            parts: [{ text: promptText }]
          }
        ],
        generationConfig: {
          response_mime_type: "application/json",
          temperature: 0.3
        }
      }
    }
  };
});

const items = $input.all();
let promptItems = [];

try {
  promptItems = $('Build Editorial Prompt Payload').all();
} catch (e) {
  promptItems = [];
}

const enrichedCandidates = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const httpResponse = item.json || {};

  // Resolve upstream input item using n8n pairedItem tracking
  let pairedIdx = item.pairedItem !== undefined ? (typeof item.pairedItem === 'number' ? item.pairedItem : item.pairedItem?.item) : i;
  if (pairedIdx === undefined || pairedIdx < 0 || pairedIdx >= promptItems.length) {
    pairedIdx = i;
  }
  const originalArticle = promptItems[pairedIdx]?.json ? { ...promptItems[pairedIdx].json } : (item.json || {});

  // Clean up prompt payload from final publication dossier
  delete originalArticle.gemini_request_payload;

  // Handle HTTP errors (e.g., 429 quota exhaustion, 503 overload)
  if (httpResponse.error) {
    enrichedCandidates.push({
      json: {
        ...originalArticle,
        pipeline_stage: "ai_analysis_failed",
        ai_error_details: httpResponse.error.message || String(httpResponse.error),
        ai_editorial_dossier: {
          topic_analysis: "AI analysis unavailable due to API rate limit or network error",
          documentary_angle: "Pending manual or retry analysis",
          suggested_title: originalArticle.title || "Untitled Documentary",
          storytelling_hooks: [
            `The unexplained paradox at the core of ${originalArticle.title || 'this discovery'}.`,
            `What researchers never expected to find beneath the surface.`,
            `Why this revelation could transform our understanding of the universe.`
          ],
          facts_requiring_verification: ["Source article details need manual verification"],
          primary_research_sources: [originalArticle.source || "Primary source pending"],
          long_video_potential: "PENDING",
          shorts_potential: "PENDING"
        }
      }
    });
    continue;
  }

  // Parse structured JSON response from Gemini
  let aiData = {};
  let parseError = false;
  try {
    const rawText = httpResponse.candidates?.[0]?.content?.parts?.[0]?.text || "{}";
    aiData = JSON.parse(rawText);
  } catch (e) {
    parseError = true;
    aiData = {};
  }

  // Ensure exactly 3 storytelling hooks are returned
  let rawHooks = Array.isArray(aiData.storytelling_hooks)
    ? aiData.storytelling_hooks.filter(h => typeof h === 'string' && h.trim().length > 0)
    : [];

  const fallbackHooks = [
    `The unexpected clue that reopened an unresolved mystery.`,
    `How an accidental observation led to a groundbreaking realization.`,
    `The profound implication that mainstream theory is struggling to explain.`
  ];

  if (rawHooks.length > 3) {
    rawHooks = rawHooks.slice(0, 3);
  } else {
    while (rawHooks.length < 3) {
      rawHooks.push(fallbackHooks[rawHooks.length]);
    }
  }

  enrichedCandidates.push({
    json: {
      ...originalArticle,
      pipeline_stage: parseError ? "ai_analysis_parse_warning" : "ai_analysis_complete",
      ai_editorial_dossier: {
        topic_analysis: aiData.topic_analysis || "Topic analysis unavailable",
        documentary_angle: aiData.documentary_angle || "Angle unavailable",
        suggested_title: aiData.suggested_title || originalArticle.title || "Untitled",
        storytelling_hooks: rawHooks,
        facts_requiring_verification: Array.isArray(aiData.facts_requiring_verification) && aiData.facts_requiring_verification.length > 0
          ? aiData.facts_requiring_verification
          : ["Primary empirical claims in original publication"],
        primary_research_sources: Array.isArray(aiData.primary_research_sources) && aiData.primary_research_sources.length > 0
          ? aiData.primary_research_sources
          : [originalArticle.source || "Primary institutional archive"],
        long_video_potential: aiData.long_video_potential || "MEDIUM",
        shorts_potential: aiData.shorts_potential || "MEDIUM"
      }
    }
  });
}

return enrichedCandidates;

// Discovered archive output
const discovered = $input.all();
return discovered.map(item => ({
  json: {
    ...item.json,
    pipeline_stage: "archived_discovery",
    editorial_note: "Discovered topic stored in background archive (below research threshold)."
  }
}));
